    /* POLISHED SIX REALMS — original vector assets and visual-only enhancements. */
    (function () {
      'use strict';
      const images = { "portal": "data:image/svg+xml;base64,", "dragon": "data:image/svg+xml;base64,", "chest": "data:image/svg+xml;base64,", "shield": "data:image/svg+xml;base64,", "temple": "data:image/svg+xml;base64,", "forest": "data:image/svg+xml;base64,", "frost": "data:image/svg+xml;base64,", "volcano": "data:image/svg+xml;base64,", "cosmos": "data:image/svg+xml;base64,", "atlantis": "data:image/svg+xml;base64," };
      const scenes = { "temple": "data:image/svg+xml;base64,", "forest": "data:image/svg+xml;base64,", "frost": "data:image/svg+xml;base64,", "volcano": "data:image/svg+xml;base64,", "cosmos": "data:image/svg+xml;base64,", "atlantis": "data:image/svg+xml;base64," };
      const themes = ['temple', 'forest', 'frost', 'volcano', 'cosmos', 'atlantis'];
      const themeNames = { temple: 'THE LOST TEMPLE', forest: 'EMERALD WILDS', frost: 'FROST CITADEL', volcano: 'EMBER FORGE', cosmos: 'STAR OBSERVATORY', atlantis: 'SUNKEN KINGDOM' };
      const themeIcons = { temple: 'temple', forest: 'forest', frost: 'frost', volcano: 'volcano', cosmos: 'cosmos', atlantis: 'atlantis' };
      const board = document.getElementById('board');
      function theme() { return document.body.dataset.boardTheme || 'temple' }
      function img(src, klass) { let im = document.createElement('img'); im.className = klass; im.src = src; im.alt = ''; im.decoding = 'async'; im.draggable = false; im.setAttribute('aria-hidden', 'true'); return im; }
      function updateStage() {
        const world = theme(); const pane = document.querySelector('#gameScreen .board-card');
        if (!pane) return;
        let scene = pane.querySelector('.rr-art-backdrop');
        if (!scene) { scene = document.createElement('div'); scene.className = 'rr-art-backdrop'; scene.setAttribute('aria-hidden', 'true'); pane.prepend(scene); }
        scene.style.backgroundImage = `linear-gradient(180deg,rgba(8,15,34,.14),rgba(7,13,27,.55)),url("${scenes[world] || scenes.temple}")`;
        const name = document.getElementById('mapThemeTitle'); if (name) name.dataset.polished = 'yes';
        const heroArt = document.querySelector('.hero-art'); if (heroArt) heroArt.style.setProperty('--rr-landscape', `url("${scenes[world] || scenes.temple}")`);
      }
      function decorate() {
        updateStage(); if (!board) return;
        const world = theme();
        board.querySelectorAll('.tile[data-tile]').forEach(tile => {
          let n = Number(tile.dataset.tile); let emblem = tile.querySelector('.tile-special');
          if (emblem) {
            let icon = emblem.querySelector('img');
            if (icon) { icon.src = images[emblem.classList.contains('realm-dragon') ? 'dragon' : 'portal']; icon.classList.add('rr-premium-icon'); }
            emblem.classList.add('rr-crafted');
            if (emblem.classList.contains('realm-portal')) {
              let spark = emblem.querySelector('.rr-portal-spark');
              if (!spark) { spark = document.createElement('span'); spark.className = 'rr-portal-spark'; spark.setAttribute('aria-hidden', 'true'); emblem.prepend(spark); }
            }
          }
          const decor = tile.querySelector('.expedition-prop');
          if (decor) { decor.textContent = ''; decor.append(img(images[themeIcons[world]], 'rr-prop-icon')); }
          const treasure = tile.querySelector('.treasure-object');
          if (treasure && !treasure.classList.contains('treasure-claimed')) {
            treasure.dataset.rrReward = 'mystery'; treasure.textContent = ''; treasure.append(img(images.chest, 'rr-treasure-icon'));
          }
        });
      }
      // Original wrapped functions handle all movement and board regeneration.
      if (typeof drawBoard === 'function') {
        const prior = drawBoard;
        drawBoard = function (...args) { const result = prior.apply(this, args); decorate(); return result; };
      }
      // Theme is changed by the existing menus and does not affect game state.
      for (const node of document.querySelectorAll('#mapThemeLive,#settingMapTheme,input[name="mapTheme"]')) {
        node.addEventListener('change', () => requestAnimationFrame(decorate));
      }
      // Upgrade the theme selection cards with actual original environment artwork.
      function updatePicker() {
        document.querySelectorAll('[data-option-theme]').forEach(card => {
          let t = card.dataset.optionTheme; let thumb = card.querySelector('.map-theme-thumb');
          if (thumb && scenes[t]) { thumb.style.backgroundImage = `linear-gradient(180deg,rgba(7,13,31,.05),rgba(7,13,31,.38)),url("${scenes[t]}")`; thumb.classList.add('rr-illustrated-thumb'); }
        });
      }
      updatePicker();
      // Keep artwork current after menu/setup switches and live board update.
      if (board) {
        const watcher = new MutationObserver(mutations => {
          if (mutations.some(m => m.type === 'childList' && [...m.addedNodes].some(n => n.nodeType === 1 && n.matches?.('.tile')))) {
            requestAnimationFrame(decorate);
          }
        }); watcher.observe(board, { childList: true });
      }
      requestAnimationFrame(decorate);
    })();

  
